# Testes da API do BrunOS contra um servidor rodando (local ou em container).
# Uso: BASE=http://127.0.0.1:8099 FIX=/tmp/bt python3 tests/apitest.py
import json, os, urllib.request, http.cookiejar, sys, io, zipfile
B=os.environ.get('BASE','http://127.0.0.1:8099')
FIX=os.environ.get('FIX','/tmp/bt')
cj=http.cookiejar.CookieJar(); op=urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj))
ok=0; bad=0
def req(method, path, body=None, raw=None, hdr=True, ctype='application/json', ua=None):
    data = raw if raw is not None else (json.dumps(body).encode() if body is not None else None)
    r=urllib.request.Request(B+path, data=data, method=method)
    if data is not None: r.add_header('Content-Type', ctype)
    if hdr: r.add_header('X-BrunOS','1')
    if ua: r.add_header('User-Agent', ua)
    try:
        resp=op.open(r); return resp.status, resp.read(), resp.headers
    except urllib.error.HTTPError as e:
        return e.code, e.read(), e.headers
def check(name, cond, extra=''):
    global ok,bad
    if cond: ok+=1; print('  ok ', name)
    else: bad+=1; print('  FALHOU', name, extra)
